// Debug utility for Seek continuous flow
// Run this in browser console to check flow status

async function debugSeekFlow() {
  console.log('🔍 Debugging Seek Continuous Flow...');

  try {
    const result = await chrome.storage.local.get([
      'seekFlowActive',
      'seekFlowState',
      'seekFlowStartTime',
      'seekFlowTabId',
      'seekFlowLastUpdate',
      'seekFlowProcessing',
      'seekJobInfo'
    ]);

    console.log('📊 Flow Status:', {
      active: result.seekFlowActive || false,
      state: result.seekFlowState || 'idle',
      processing: result.seekFlowProcessing || false,
      startTime: result.seekFlowStartTime ? new Date(result.seekFlowStartTime).toLocaleString() : 'N/A',
      tabId: result.seekFlowTabId || 'N/A',
      lastUpdate: result.seekFlowLastUpdate ? new Date(result.seekFlowLastUpdate).toLocaleString() : 'N/A',
      elapsed: result.seekFlowStartTime ? Math.round((Date.now() - result.seekFlowStartTime) / 1000) + 's' : 'N/A',
      jobTitle: result.seekJobInfo?.job_title || 'N/A',
      company: result.seekJobInfo?.company || 'N/A'
    });

    // Check current page elements
    const stepElement = document.querySelector('[aria-current="step"]');
    const applyButton = document.querySelector('[data-automation="job-detail-apply"]');
    const successElement = document.querySelector('#applicationSent');

    console.log('🎯 Current Page:', {
      url: window.location.href,
      hasStepElement: !!stepElement,
      currentStep: stepElement?.textContent?.trim() || 'N/A',
      hasApplyButton: !!applyButton,
      applyButtonText: applyButton?.textContent?.trim() || 'N/A',
      hasSuccessElement: !!successElement,
      isSeekSite: window.location.href.toLowerCase().includes('seek.com'),
      autofillInProgress: window.seekAutofillInProgress || false,
      lastAutofillTime: window.seekLastAutofillTime ? new Date(window.seekLastAutofillTime).toLocaleString() : 'N/A'
    });

  } catch (error) {
    console.error('❌ Error debugging flow:', error);
  }
}

async function clearSeekFlow() {
  console.log('🧹 Clearing Seek flow...');

  try {
    await chrome.storage.local.remove([
      'seekFlowActive',
      'seekFlowState', 
      'seekJobInfo',
      'seekFlowStartTime',
      'seekFlowTabId',
      'seekFlowLastUpdate',
      'seekFlowProcessing'
    ]);

    console.log('✅ Flow cleared successfully');
  } catch (error) {
    console.error('❌ Error clearing flow:', error);
  }
}

// Auto-run debug on load
debugSeekFlow();

console.log('🛠️ Debug utilities loaded:');
console.log('  - debugSeekFlow() - Check current flow status');
console.log('  - clearSeekFlow() - Clear/reset the flow');

/* eslint-env browser */
import React, { useEffect, useRef, useState } from "react";
import { createRoot } from "react-dom/client";
import ActionButtons from "../components/ActionButtons.jsx";
import {
  invokeActionButton,
  subscribeActionButtonState,
} from "../utils/actionButtonsBridge";

/** ---------- 基础配置 ---------- */
const INJECT_ID = "jobgen-indeed-pill";
const DEBOUNCE_MS = 120;

/** Smart Apply 表单不注入（那里由你的 SmartApply 面板负责） */
const isSmartApply = () =>
  /(^|\.)smartapply\.indeed\.com$/i.test(location.hostname);

/** 可能的 Apply 按钮选择器（兼容多版本） */
const APPLY_BTN_SELECTORS = [
  "#indeedApplyButton",
  '[data-tn-element="applyButton"]',
  '[data-qa="apply-button"]',
  '[data-testid*="apply"]',
  'a[role="button"]',
  "button",
];

/** 候选挂载容器：会选离 Apply 最近的一个 */
const HOST_SELECTOR_CANDIDATES = [
  '[data-testid="inlineHeader-actions"]',
  "#applyButtonLinkContainer",
  ".jobsearch-DesktopStickyContainer",
  ".jobsearch-JobInfoHeader-title-container",
  '[data-tn-component="jobHeader"]',
];

/** ---------- 小工具 ---------- */
const rafDebounce = (fn, wait = DEBOUNCE_MS) => {
  let t = 0;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => requestAnimationFrame(() => fn(...args)), wait);
  };
};

/** 递归查询（含 shadowRoot） */
const $all = (root, selectors) => {
  const out = [];
  const visit = (node) => {
    if (!node) return;
    if (node.querySelectorAll) {
      selectors.forEach((sel) =>
        node.querySelectorAll(sel).forEach((el) => out.push(el))
      );
    }
    const sr = node.shadowRoot;
    if (sr) visit(sr);
    if (node.children) Array.from(node.children).forEach(visit);
  };
  visit(root);
  return out;
};

/** ---------- DOM 定位 ---------- */
function findApplyButton() {
  return $all(document, APPLY_BTN_SELECTORS).find((btn) => {
    if (!btn || btn.offsetParent === null) return false;
    const txt = (btn.innerText || btn.textContent || "").trim();
    return /(apply|申请)/i.test(txt);
  });
}

function findHostContainer(applyBtn) {
  const hosts = $all(document, HOST_SELECTOR_CANDIDATES).filter(
    (n) => n && n.offsetParent !== null
  );
  if (!hosts.length) return applyBtn?.parentElement || null;

  const ar = applyBtn.getBoundingClientRect();
  const dist = (r) =>
    Math.hypot(
      (r.left + r.right) / 2 - (ar.left + ar.right) / 2,
      (r.top + r.bottom) / 2 - (ar.top + ar.bottom) / 2
    );

  let best = null,
    bestScore = Infinity;
  for (const h of hosts) {
    const s = dist(h.getBoundingClientRect());
    if (s < bestScore) {
      best = h;
      bestScore = s;
    }
  }
  return best;
}

/** ---------- 渲染/卸载 ---------- */
let rootRef = null;
let containerRef = null;
let mountedTo = null;

function unmount() {
  try {
    rootRef?.unmount();
  } catch {}
  rootRef = null;
  if (containerRef?.parentNode) containerRef.parentNode.removeChild(containerRef);
  containerRef = null;
  mountedTo = null;
}

/** 动态调用你可能导出的 autofill/apply（若无则静默） */
async function tryAutofillIndeed() {
  try {
    const mod = await import("./indeed"); // 若文件存在且导出，则调用
    if (typeof mod.autofillIndeed === "function") return mod.autofillIndeed();
  } catch {}
}
async function tryApplyIndeed() {
  try {
    const mod = await import("./indeed");
    if (typeof mod.applyIndeed === "function") return mod.applyIndeed();
  } catch {}
}

/** ---------- 仅 Indeed 生效的包装按钮（同步 Applying/Applied 状态） ---------- */
const INDEED_LAST_ACTION_KEY = "jobgen:last_action";
const INDEED_ACTION_AUTO_APPLY = "auto_apply";

function parseIndeedJkFromUrl(href) {
  try {
    const u = new URL(href);
    // 首先取 ?jk=
    const jk = u.searchParams.get("jk");
    if (jk) return jk;
    // 再尝试 viewjob?jk=xxx 之外的路径（保底可以扩展）
    // e.g. /company/xxx/jobs/yyy?jk=zz 已在上面覆盖
    return null;
  } catch {
    return null;
  }
}

function getJobStatusKeyForUrl(href) {
  const jk = parseIndeedJkFromUrl(href);
  return jk ? `indeed_job_${jk}_status` : null;
}

/**
 * 这个包装组件只在 Indeed 注入处使用：
 * - hasActiveFlow: 由 jobgen:last_action === 'auto_apply' 推断
 * - jobStatus: 读取 indeed_job_${jk}_status === 'Applied' 或 window.__jobgen_job_status === 'Applied'
 * - platformKey 固定为 'indeed' 以应用 Indeed 的视觉预设
 */
function IndeedActionButtons({ onAction, onApply }) {
  const [hasActiveFlow, setHasActiveFlow] = useState(false);
  const [jobStatus, setJobStatus] = useState(null);
  const [currentSite, setCurrentSite] = useState("indeed");
  const jobStatusKeyRef = useRef(getJobStatusKeyForUrl(window.location.href));

  // 订阅 bridge，仅用于确认 currentSite（不会修改 bridge）
  useEffect(() => {
    const unsub = subscribeActionButtonState((s) => {
      const site = (s?.currentSite || "").toLowerCase();
      setCurrentSite(site || "indeed");
    });
    return unsub;
  }, []);

  // 监听 last_action → hasActiveFlow
  useEffect(() => {
    if (currentSite !== "indeed") return;

    let cancelled = false;
    const read = async () => {
      try {
        const r = await chrome.storage.local.get([INDEED_LAST_ACTION_KEY]);
        if (cancelled) return;
        setHasActiveFlow(r[INDEED_LAST_ACTION_KEY] === INDEED_ACTION_AUTO_APPLY);
      } catch {}
    };

    const onChanged = (changes, area) => {
      if (area !== "local") return;
      if (changes[INDEED_LAST_ACTION_KEY]) {
        const v = changes[INDEED_LAST_ACTION_KEY].newValue;
        setHasActiveFlow(v === INDEED_ACTION_AUTO_APPLY);
      }
    };

    read();
    chrome.storage.onChanged.addListener(onChanged);
    return () => {
      cancelled = true;
      chrome.storage.onChanged.removeListener(onChanged);
    };
  }, [currentSite]);

  // 读取/监听当前职位的已投递状态 → jobStatus
  useEffect(() => {
    if (currentSite !== "indeed") return;

    const readStatus = async () => {
      // 方案 A：全局标志
      if (window.__jobgen_job_status === "Applied") {
        setJobStatus("Applied");
        return;
      }
      // 方案 B：storage 中的 per-job 状态
      const key = jobStatusKeyRef.current;
      if (!key) {
        setJobStatus(null);
        return;
      }
      try {
        const r = await chrome.storage.local.get([key]);
        if (r[key] === "Applied") setJobStatus("Applied");
        else setJobStatus(null);
      } catch {
        setJobStatus(null);
      }
    };



    // 初次读取
    readStatus();

    const onChanged = (changes, area) => {
      if (area !== "local") return;
      const key = jobStatusKeyRef.current;
      if (!key) return;
      if (changes[key]) {
        const v = changes[key].newValue;
        setJobStatus(v === "Applied" ? "Applied" : null);
      }
    };

    // 监听 storage 更新
    chrome.storage.onChanged.addListener(onChanged);

    // 监听 URL 变化（本文件已在 setup 里派发 'jobgen:urlchange'）
    const onUrlChange = () => {
      jobStatusKeyRef.current = getJobStatusKeyForUrl(window.location.href);
      readStatus();
    };
    window.addEventListener("jobgen:urlchange", onUrlChange);

    return () => {
      chrome.storage.onChanged.removeListener(onChanged);
      window.removeEventListener("jobgen:urlchange", onUrlChange);
    };
  }, [currentSite]);

  return (
    <ActionButtons
      onAction={onAction}
      onApply={onApply}
      hasActiveFlow={hasActiveFlow}
      jobStatus={jobStatus}
      platformKey="indeed"
    />
  );
}

/** ---------- 渲染逻辑 ---------- */
function renderButtons() {
  // 1) SmartApply 页面不注入
  if (isSmartApply()) {
    unmount();
    return;
  }

  // 2) 找到 Apply 按钮；没有就不注入
  const applyBtn = findApplyButton();
  if (!applyBtn) { unmount(); return; }
  const btnText = (applyBtn.innerText || applyBtn.textContent || "").trim().toLowerCase();
  if (!btnText.includes("apply now")) { unmount(); return; }

  // 3) 找“整排按钮容器”（flex 行）
  const row =
    applyBtn.closest('[data-testid="jobsearch-ViewJobButtons-container"]') ||
    applyBtn.closest('.jobsearch-ViewJobButtons-container');

  // 没找到 row 就退回“插在 apply 后面”（但优先用 row，避免变形）
  const mountAfterEl = row || applyBtn;

  // 4) 已经挂在当前容器后面就跳过
  if (mountedTo === mountAfterEl && containerRef?.isConnected) return;

  // 5) 重新挂载
  unmount();

  // —— 包一层 wrapper：与按钮行彻底分离（不当其 flex 子项）
  const wrapper = document.createElement("div");
  wrapper.id = INJECT_ID + "-wrapper";
  wrapper.style.display = "block";
  wrapper.style.marginTop = "8px";
  wrapper.style.marginLeft = window.location.href.includes("viewjob")? "0px": "16px";

  // 真正的挂载容器
  containerRef = document.createElement("div");
  containerRef.id = INJECT_ID;         // #jobgen-indeed-pill
  containerRef.style.display = "block";
  containerRef.style.boxSizing = "border-box";

  // 关键：插在“整排按钮容器”的后面（afterend），避免影响该行布局
  try {
    mountAfterEl.insertAdjacentElement("afterend", wrapper);
  } catch {
    const host = findHostContainer(applyBtn);
    (host || document.body).appendChild(wrapper);
  }
  wrapper.appendChild(containerRef);

  // 6) 一次性注入局部样式（仅作用于我们容器）
  (function injectScopedStylesOnce() {
    const STYLE_ID = INJECT_ID + "-style";
    if (document.getElementById(STYLE_ID)) return;
    const style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = `
      /* 仅作用于我们自己的容器，避免外溢 */
      #${INJECT_ID}, #${INJECT_ID} * { box-sizing: border-box; }
      #${INJECT_ID} { font: inherit; color: inherit; }
      /* 若有通用类（.btn/.card 等），请加 #${INJECT_ID} 前缀去写样式 */
      /* #${INJECT_ID} .jg-btn { ... } */
      /* #${INJECT_ID} .jg-card { ... } */

      /* 可选：让我们按钮高度更接近 Indeed（自行按需调整/删除） */
      #${INJECT_ID} button {
        height: 44px;
        line-height: 44px;
        border-radius: 10px;
      }
    `;
    document.head.appendChild(style);
  })();

  // 7) 点击行为：bridge 优先、兜底原生
  const onAction = async (action) => {
    if (invokeActionButton(action)) return;

    if (action === "save") {
      const candidates = [
        '[data-tn-element="save-job-button"]',
        'button[aria-label*="Save" i]',
        'button[data-testid*="save" i]',
      ];
      const btn =
        $all(document, candidates)
          .filter((b) => b && b.offsetParent !== null)
          .find((b) => /save/i.test((b.innerText || b.textContent || "").trim())) || null;
      btn?.click();
      return;
    }

    if (action === "autofill") {
      await tryAutofillIndeed(); // 若不存在则静默
      return;
    }

    if (action === "apply") {
      if (!(await tryApplyIndeed())) {
        findApplyButton()?.click();
      }
      return;
    }
  };

  // 8) 渲染 React 组件（改为使用 Indeed 包装版，自动同步 Applying/Applied）
  rootRef = createRoot(containerRef);
  rootRef.render(
    <IndeedActionButtons
      onAction={onAction}
      onApply={() => onAction("apply")}
    />
  );

  // 9) 记录挂载目标（用于去重）
  mountedTo = mountAfterEl;
}

const reevaluate = rafDebounce(renderButtons);

/** ---------- 对外 API（幂等） ---------- */
export function setupIndeedJobGenButtons() {
  // 首评估
  reevaluate();

  // 观察 DOM（Indeed SPA 场景）
  const mo = new MutationObserver(reevaluate);
  mo.observe(document.documentElement, { childList: true, subtree: true });

  // 视口/焦点变动
  window.addEventListener("resize", reevaluate, { passive: true });
  window.addEventListener("focus", reevaluate, { passive: true });

  // URL 变化监听（pushState/replaceState）
  const patch = (k) => {
    const raw = history[k];
    history[k] = function (...args) {
      const r = raw.apply(this, args);
      window.dispatchEvent(new Event("jobgen:urlchange"));
      return r;
    };
  };
  if (!window.__jobgenPatchedHistory) {
    window.__jobgenPatchedHistory = true;
    patch("pushState");
    patch("replaceState");
    window.addEventListener("popstate", () =>
      window.dispatchEvent(new Event("jobgen:urlchange"))
    );
  }
  window.addEventListener("jobgen:urlchange", reevaluate);

  // 返回销毁函数
  return () => {
    mo.disconnect();
    window.removeEventListener("resize", reevaluate);
    window.removeEventListener("focus", reevaluate);
    window.removeEventListener("jobgen:urlchange", reevaluate);
    unmount();
  };
}

import { mapStructuredQuestion } from "../services/infoMapping.js";
import {
  submitJobApplication,
  submitJobApplicationOutcome,
  getJWT,
  getStoredFAQData
} from "../services/apiService.js";


// ======================= 基础工具 =======================
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log("[Indeed]", ...a);



let BUSY = false;
let PAGE_ID = 0;          
let ACTIVE_RUN_ID = null; 
let APPLY_KEY = false;
let CURRENT_ID = '';
let SUCCESS_ALREADY_REPORTED = false;


function newPageId() { PAGE_ID += 1; return PAGE_ID; }
function newRunId()  { ACTIVE_RUN_ID = `${PAGE_ID}:${Date.now()}:${Math.random()}`; return ACTIVE_RUN_ID; }
function isActive(runId) { return runId && runId === ACTIVE_RUN_ID; }

// ---------- storage keys ----------
const CURRENT_ID_KEY = "jobgen:current_job_id";
const LAST_ACTION_KEY = "jobgen:last_action"; // "apply_clicked" | "auto_apply" | null
const LAST_JOB_INFO_KEY = "jobgen:last_job_info";
const STEP_FINISH_KEY = "jobgen:indeed_step_finished";

const ACTION_APPLY_CLICKED = "apply_clicked";
const ACTION_AUTO_APPLY = "auto_apply";
const ACTION_AUTOFILL = "auto_fill";

// ==== Indeed SmartApply 常驻 Progress（仅 Autofill）====
import { createProgressEmitters } from '../utils/progressBridge.js';

const prog = createProgressEmitters('indeed');

const pageTitleMap = {
  documents: 'Documents',
  contact: 'Contact info',
  questions: 'Employer questions',
  review: 'Review & Submit',
  success: 'Submitted',
  unknown: 'Working…',
};
const titleOf = (p) => pageTitleMap[p] || pageTitleMap.unknown;

function onSmartApply() {
  return /(^|\.)smartapply\.indeed\.com$/i.test(location.hostname);
}
function forceShowProgress(mode = 'autofill') {
  document.dispatchEvent(new CustomEvent('jobgen-progress-visibility', {
    detail: { site: 'indeed', visible: true, mode, _ts: Date.now() }
  }));

}
async function isInJobGenFlow() {
  try {
    const last = await storageGet([LAST_ACTION_KEY]);
    const act = last[LAST_ACTION_KEY];

    if (act === ACTION_AUTO_APPLY || act === ACTION_AUTOFILL) {
      return true;
    }
    return false;
  } catch (e) {
    console.warn('[Indeed] isInJobGenFlow() error:', e);
    return false;
  }
}
async function keepFinished(message = 'Ready — click Autofill') {

  const inFlow = await isInJobGenFlow();
  if (!inFlow) {
    return;
  }

  const last = await storageGet([LAST_ACTION_KEY]);
    if (last[LAST_ACTION_KEY] === ACTION_AUTO_APPLY) {
       forceShowProgress('apply');
       prog.start('apply', 'Start applying.', 'filling', { message });
       if (!BUSY && onSmartApply()) {
          try { await runFullApplyFlow(); } catch (e) { console.error(e); }
       }
    return;
    }

  if (APPLY_KEY) return;
  if (!onSmartApply()) return;

  const page = (typeof detectPage === 'function' ? detectPage(): 'unknown');
  const alreadyFinished = await isThisUrlFinished();

  forceShowProgress('autofill');

  if (alreadyFinished) {
    prog.start('autofill', 'Click Next to continue.', 'finished', {message: 'Finished - click Next to continue.'});
  }else {
    prog.start('autofill', 'Please click autofill.', 'finished', { message });
  }

}

// —— Autofill：进入 filling，填完回 finished
async function autofillCurrentPageWithProgress() {
  if (!onSmartApply()) return;

  const page = (typeof detectPage === 'function' ? detectPage() : 'unknown');
  const title = titleOf(page);
  prog.start('autofill', title, 'filling', { message: 'Filling current form…' });

  try {
    await fillCurrentForm(); 
    prog.update(title, 'finished', { message: 'Done. Review and click Next' });
    await markStepFinishedForCurrentUrl();
  } catch (e) {
    prog.error(e?.message || 'Autofill failed. You can edit manually.');
  }
}

// —— Next：仅帮点 Continue；切页后再次保持 finished
async function pressContinueThenIdle() {
  if (!onSmartApply()) return;

  await clearStepFinishedUrl();
  try {
    const ok = await clickPrimary('Continue from panel');
    if (!ok) {
      const form = document.querySelector('form');
      form?.dispatchEvent(new Event('change', { bubbles: true }));
      await new Promise(r => setTimeout(r, 150));
      await clickPrimary('Continue fallback');
    }
  } catch (e) {
    prog.error(e?.message || 'Failed to continue');
  }
}

async function clearStepFinishedUrl() {
  try {
    await storageSet({
      [STEP_FINISH_KEY]: ''
    });
  } catch (e) {
    console.warn('[Indeed] clearStepFinishedUrl error:', e);
  }
}
function isTransitionUrl(href) {
  try {
    const u = new URL(href);
    const path = u.pathname.toLowerCase();
    if (/postresumeapply/i.test(path)) return true;
    return false;
  } catch {
    return false;
  }
}

async function markStepFinishedForCurrentUrl() {
  try {
    const pageName = detectPage();
    if (
      pageName === "transition" ||
      pageName === "unknown" ||
      pageName === "job" ||         
      pageName === "success"       
    ) {
      console.log("[Indeed] skip markStepFinishedForCurrentUrl for page:", pageName, location.href);
      return;
    }

    await storageSet({
      [STEP_FINISH_KEY]: pageName
    });
    console.log("[Indeed] markStepFinishedForCurrentUrl stored:", pageName, "at", location.href);
  } catch (e) {
    console.warn("[Indeed] markStepFinishedForCurrentUrl error:", e);
  }
}

async function isThisUrlFinished() {
  try {
    const st = await storageGet([STEP_FINISH_KEY]);
    const finishedPage = st[STEP_FINISH_KEY];  
    const currentPage  = detectPage();         

    if (!finishedPage) return false;

    if (
      currentPage === "transition" ||
      currentPage === "unknown"
    ) {
      return false;
    }


    const VALID_PAGES = new Set([
      "contact",
      "relevant-experience",
      "questions",
      "documents",
      "review",
      "success"
    ]);
    if (!VALID_PAGES.has(finishedPage)) {
      return false;
    }

    return finishedPage === currentPage;
  } catch (e) {
    console.warn("[Indeed] isThisUrlFinished error:", e);
    return false;
  }
}

function attachProgressLifecyle() {
  const refresh = async () => {
  if (!onSmartApply()) return;

  const inFlow = await isInJobGenFlow();
  const p = (typeof detectPage === 'function' ? detectPage() : 'unknown');

  if (p === 'success') {

    if (inFlow) {
      try {
        const mode = await getModeForSuccessPanel();
         let jobId = '';
        try {
          const cur = await storageGet([CURRENT_ID_KEY]);
          jobId = cur[CURRENT_ID_KEY] || '';
        } catch (e) {
          console.warn('[Indeed][attachProgressLifecyle.refresh] cannot read CURRENT_ID_KEY', e);
        }

        try {
          await handleSuccess(jobId);
        } catch (err) {
          console.error('[Indeed][attachProgressLifecyle.refresh] handleSuccess() failed:', err);
        }

        prog.start(
          mode,
          titleOf('success'),
          'submitted',
          { message: 'Application submitted!' }
        );
      } catch (e) {
        console.warn('[Indeed] prog.start failed on success page', e);
      }
    }
    return;
  }

  if (!inFlow) {
    return;
  }

  await handleSmartApplyStepChange("refresh");
};


  window.addEventListener('urlchange', refresh);
  window.addEventListener('pageshow', refresh);
  document.addEventListener('visibilitychange', () => {
