      const interval = 100;
      let elapsedTime = 0;

      const checkElement = setInterval(() => {
        let element = document.querySelector(selector);
        if (element) {
          clearInterval(checkElement);
          resolve(element);
        }
        elapsedTime += interval;
        if (elapsedTime >= timeout) {
          clearInterval(checkElement);
          reject(new Error(`Timeout: ${selector} not found`));
        }
      }, interval);
    });
