  async handleResumeUploadErrors() {
    try {
      // Wait a bit for any error messages to appear
      await new Promise(r => setTimeout(r, 1000));

      // Look for common error indicators
      const errorSelectors = [
        // Error messages
        '[class*="error"]',
        '[class*="Error"]',
        '[data-testid*="error"]',
        '.ms-MessageBar--error',
        '.ms-MessageBar--warning',
        // Duplicate file indicators
        '[class*="duplicate"]',
        '[class*="already"]',
        // General message containers
        '[role="alert"]',
        '.ms-MessageBar',
        '[class*="message"]'
      ];

      let errorFound = false;
      let errorMessage = '';

      for (const selector of errorSelectors) {
        const errorElements = document.querySelectorAll(selector);
        for (const element of errorElements) {
          const text = element.textContent?.toLowerCase() || '';
          // Check for duplicate/same file error patterns
          if (text.includes('duplicate') || 
              text.includes('already') || 
              text.includes('same') ||
              text.includes('identical') ||
              text.includes('exists')) {
            errorFound = true;
            errorMessage = element.textContent?.trim() || 'Duplicate file detected';
            console.log(`🔍 Detected resume upload error: ${errorMessage}`);
            break;
          }
        }
        if (errorFound) break;
      }

      if (errorFound) {
        console.log(`⚠️ Resume upload error detected: ${errorMessage}`);
        console.log('🔄 Attempting to close error dialog...');

        // Look for close buttons
        const closeSelectors = [
          // Specific Microsoft close button pattern
          'button.ms-Button.ms-Button--icon[aria-label="Close popup modal"]',
          'button[aria-label="Close popup modal"]',
          'button.ms-Button--icon:has(i[data-icon-name="Cancel"])',
          // General close button patterns
          'button[aria-label*="close"]',
          'button[aria-label*="Close"]',
          'button[title*="close"]',
          'button[title*="Close"]',
          'button.ms-Dialog-button--close',
          'button[data-testid*="close"]',
          'button[class*="close"]',
          'button[class*="Close"]',
          '.ms-Button--icon[aria-label*="close"]',
          // X button patterns with Cancel icon
          'button:has(i[data-icon-name="Cancel"])',
          'button:has(svg[data-icon-name="Cancel"])',
          'button:has(svg[data-icon-name="ChromeClose"])',
          // Generic close patterns
          'button[type="button"]:has([class*="icon"])'
        ];

        let closeButtonFound = false;
        for (const selector of closeSelectors) {
          try {
            const closeButtons = document.querySelectorAll(selector);
            for (const btn of closeButtons) {
              const btnText = btn.textContent?.toLowerCase() || '';
              const ariaLabel = btn.getAttribute('aria-label')?.toLowerCase() || '';
              const title = btn.getAttribute('title')?.toLowerCase() || '';

              if (btnText.includes('close') || 
                  ariaLabel.includes('close') || 
                  title.includes('close') ||
                  ariaLabel === 'close popup modal' ||
                  btn.querySelector('i[data-icon-name="Cancel"]') ||
                  btn.querySelector('svg[data-icon-name*="Close"]') ||
                  btn.querySelector('svg[data-icon-name*="Cancel"]')) {
                console.log(`🎯 Found close button: ${btnText || ariaLabel || title || 'icon button'}`);
                btn.click();
                closeButtonFound = true;
                await new Promise(r => setTimeout(r, 500));
                console.log('✅ Successfully closed error dialog');
                break;
              }
            }
            if (closeButtonFound) break;
          } catch (e) {
            // Continue trying other selectors
            continue;
          }
        }

        if (!closeButtonFound) {
          console.warn('⚠️ Could not find close button for error dialog');
          // Try pressing Escape key as fallback
          document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27 }));
          console.log('⌨️ Attempted to close dialog with Escape key');
        }
      } else {
        console.log('✅ No resume upload errors detected');
      }
    } catch (err) {
      console.error('❌ Error while handling resume upload errors:', err);
    }
  }

