            {/* Footer Section */}
            <div
              id="footer"
              style={{
                position: 'sticky',
                bottom: 0,
                width: '100%',
                padding: '0 0',
                backgroundColor: 'white',
                borderTop: '2px solid #ddd',
                zIndex: 99999,
                display: 'flex',
                alignItems: 'center',
                borderBottomLeftRadius: `${CONTAINER_BORDER_RADIUS}px`,
                borderBottomRightRadius: `${CONTAINER_BORDER_RADIUS}px`
              }}
            >
