          description: description || "",
          company: companyName || "",
          job_title: jobTitle || "",
          job_id: jobId || "",
          job_portal: "GLASSDOOR"
        });

        const normalized = normalizeJobMatch(resp, jobId);
        console.log("[Glassdoor] ✅ Match result:", normalized);

        setJobData(normalized);

