      return null;
    }

    const body = JSON.stringify({});
    console.log('=== FAQ API payload:', JSON.parse(body));

    const res = await fetch("https://candidates.jobgen.ai/api/1.1/wf/jobgen_faq", {
      method: "POST",
      headers: {
