export function isLinkedInSubmitStage() {
  return linkedinSubmitStage;
}
const EASY_APPLY_INACTIVITY_TIMEOUT_MS = 2 * 60 * 1000; // safety valve

// Builds a reusable Easy Apply watcher that shares modal state across consumers.
export function createEasyApplyModalMonitor(initialOptions = {}) {
  const {
    context: initialContext = 'autofill',
    onModalReady: initialOnModalReady,
    onModalDismissed: initialOnModalDismissed,
    onReviewStep: initialOnReviewStep
  } = initialOptions || {};

  let running = false;
  let modal = null;
  let rafId = null;
  let observer = null;
  let aborted = false;
  let abortReject = null;
  let abortPromise = null;
  let emittedReview = false;
  let inactivityTimer = null;
  let currentContext = initialContext;

  const modalReadyListeners = new Set();
  const modalDismissedListeners = new Set();
  const reviewStepListeners = new Set();

  const observerOptions = { childList: true, subtree: true };
  let observedShadowRoots = new WeakSet();

  // Refresh the abort promise that signals modal dismissal.
  const resetAbortPromise = () => {
    abortPromise = new Promise((_, reject) => {
      abortReject = reject;
    });
    aborted = false;
  };

  // Stop the inactivity safeguard timer if it is running.
  const clearInactivityTimer = () => {
    if (inactivityTimer) {
      clearTimeout(inactivityTimer);
      inactivityTimer = null;
    }
  };

  // Restart the inactivity safeguard whenever we observe activity.
  const resetInactivityTimer = () => {
    if (EASY_APPLY_INACTIVITY_TIMEOUT_MS <= 0) return;
    clearInactivityTimer();
    inactivityTimer = setTimeout(() => {
      console.warn('⚠️ Easy Apply monitor timed out due to inactivity. Aborting watcher.');
      abort(new Error('LinkedIn Easy Apply monitor timed out due to inactivity'));
    }, EASY_APPLY_INACTIVITY_TIMEOUT_MS);
  };

  // Cancel any pending RAF-driven polling loop iterations.
  const stopRaf = () => {
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
  };

  // Disconnect DOM observers and clear the tracked shadow roots.
  const disconnectObserver = () => {
    observer?.disconnect();
    observer = null;
    observedShadowRoots = new WeakSet();
  };

  // Register a listener in the provided set and return its remover.
  const addListener = (set, listener) => {
    if (typeof listener !== 'function') return () => {};
    set.add(listener);
    return () => {
      set.delete(listener);
    };
  };

  // Attach callback hooks for modal lifecycle events.
  const registerCallbacks = ({ onModalReady, onModalDismissed, onReviewStep } = {}) => {
    const removers = [];

    if (typeof onModalReady === 'function') {
      removers.push(addListener(modalReadyListeners, onModalReady));
      if (modal && running) {
        try {
          onModalReady(modal);
        } catch (error) {
          console.error('❌ Error in Easy Apply monitor immediate onModalReady handler:', error);
        }
      }
    }

    if (typeof onModalDismissed === 'function') {
      removers.push(addListener(modalDismissedListeners, onModalDismissed));
    }

    if (typeof onReviewStep === 'function') {
      removers.push(addListener(reviewStepListeners, onReviewStep));
      if (emittedReview && modal) {
        try {
          const formContainer = modal.querySelector('.jobs-easy-apply-modal__content');
          onReviewStep((formContainer && getFormPageTitle(formContainer)) || '', modal);
        } catch (error) {
          console.error('❌ Error in Easy Apply monitor immediate onReviewStep handler:', error);
        }
      }
    }

    return () => {
      removers.forEach((remove) => {
        try {
          remove();
        } catch (error) {
          console.error('❌ Error removing Easy Apply monitor listener:', error);
        }
      });
    };
  };

  // Update logging context and reset submit-stage tracking.
  const setContext = (value) => {
    currentContext = value || 'autofill';
    setLinkedInSubmitStage(false);
    resetSubmitAttempted();
    detachSubmitClickListener();
  };

  // Abort monitoring, reject waiters, and clear internal state.
  const abort = (reason) => {
    if (aborted) return;
    aborted = true;
    clearInactivityTimer();
    stopRaf();
    disconnectObserver();
    running = false;
    modal = null;
    emittedReview = false;
    setLinkedInSubmitStage(false);
    resetSubmitAttempted();
    detachSubmitClickListener();
    const error = reason instanceof Error ? reason : new Error(reason || 'LinkedIn Easy Apply monitor aborted');
    try {
      abortReject?.(error);
    } catch (emitError) {
      console.warn('⚠️ Easy Apply monitor abort rejection failed:', emitError);
    }
  };

  // Notify listeners that the modal is present and ready.
  const emitModalReady = (node) => {
    resetInactivityTimer();
    detachSubmitClickListener();
    resetSubmitAttempted();
    for (const listener of Array.from(modalReadyListeners)) {
      try {
        listener(node);
      } catch (error) {
        console.error('❌ Error in Easy Apply monitor onModalReady handler:', error);
      }
    }
  };

  // Notify listeners that the modal was dismissed.
  const emitModalDismissed = () => {
    clearInactivityTimer();
    releaseLinkedinLockBoth(currentContext, 'autofill', 'auto-apply');
    for (const listener of Array.from(modalDismissedListeners)) {
      try {
        listener();
      } catch (error) {
        console.error('❌ Error in Easy Apply monitor onModalDismissed handler:', error);
      }
    }
    setLinkedInSubmitStage(false);
    detachSubmitClickListener(); // tear down submit tracking when modal goes away

    const attempted = submitAttempted;
    resetSubmitAttempted();

    const immediateModal = scanForSubmissionSuccess();
    if (immediateModal) {
      notifySubmissionSuccess(immediateModal); // success landed after dismissal; reuse submission handler
      return;
    }

    if (attempted) {
      // A click or dismissed modal is not proof of submission.
      const confirmationVersion = submissionConfirmationVersion;
      setTimeout(() => {
        if (submissionConfirmationVersion !== confirmationVersion) return;
        const successModal = scanForSubmissionSuccess();
        if (successModal) {
          notifySubmissionSuccess(successModal);
        } else if (!locateEasyApplyModal()) {
          const { error: errorProgress } = createProgressEmitters('linkedin');
          errorProgress('Submission could not be confirmed. Check LinkedIn before trying again.');
        }
      }, 2500);
      return;
    }

    try {
      const { error: errorProgress } = createProgressEmitters('linkedin');
      errorProgress('Application closed by user');
    } catch (progressError) {
      console.warn('⚠️ Unable to emit LinkedIn dismissal progress update:', progressError);
    }
  };

  // Notify listeners that the review/submit step is active.
  const emitReviewStep = (title) => {
    resetInactivityTimer();
    for (const listener of Array.from(reviewStepListeners)) {
      try {
        listener(title, modal);
      } catch (error) {
        console.error('❌ Error in Easy Apply monitor onReviewStep handler:', error);
      }
    }
  };

  // Detect whether the submit CTA is visible inside the modal.
  const inspectFormState = () => {
    if (!modal) return;
    const formContainer = modal.querySelector('.jobs-easy-apply-modal__content');
    if (!formContainer) return;

    const submitButton = modal.querySelector(SUBMIT_APPLICATION_SELECTOR);
    if (submitButton) {
      if (!emittedReview) {
        emittedReview = true;
        const title = getFormPageTitle(formContainer) || 'Review your application';
        emitReviewStep(title);
        console.log('=== Review stage detected via submit button');
      }
      setLinkedInSubmitStage(true);
      attachSubmitClickListener(submitButton); // watch for manual submit clicks
    } else {
      emittedReview = false;
      setLinkedInSubmitStage(false);
      detachSubmitClickListener(); // button gone, stop tracking
    }
  };

  // Make sure the interop shadow root is also being observed.
  const ensureShadowObservation = () => {
    const outlet = document.querySelector('#interop-outlet');
    if (outlet?.shadowRoot && observer && !observedShadowRoots.has(outlet.shadowRoot)) {
      observer.observe(outlet.shadowRoot, observerOptions);
      observedShadowRoots.add(outlet.shadowRoot);
    }
  };

  // Core polling loop: refresh modal reference and state flags.
  const evaluateModalState = () => {
    if (!running) return;

    resetInactivityTimer();

    if (!modal || !isModalStillAttached(modal)) {
      const latestModal = locateEasyApplyModal();
      if (latestModal && latestModal !== modal) {
        modal = latestModal;
        emittedReview = false;
        setLinkedInSubmitStage(false);
        resetSubmitAttempted();
        detachSubmitClickListener(); // modal replaced, reset submit listener
        emitModalReady(latestModal);
      } else if (!latestModal) {
        if (modal) {
          emitModalDismissed();
        }
        abort('LinkedIn Easy Apply modal dismissed');
        return;
      } else {
        emitModalDismissed();
        abort('LinkedIn Easy Apply modal dismissed');
        return;
      }
    }

    if (!modal) {
      return;
    }

    if (modal.getAttribute('aria-hidden') === 'true') {
      emitModalDismissed();
      abort('LinkedIn Easy Apply modal dismissed');
      return;
    }

    inspectFormState();
  };

  // Schedule another evaluation on the next animation frame.
  const scheduleEvaluation = () => {
    if (!running) return;
    ensureShadowObservation();
    evaluateModalState();
    rafId = requestAnimationFrame(scheduleEvaluation);
  };

  // Begin monitoring and resolve with the active modal element.
  const start = async () => {
    if (running) {
      resetInactivityTimer();
      return modal;
    }

    resetAbortPromise();
    running = true;
    emittedReview = false;
    setLinkedInSubmitStage(false);
    resetSubmitAttempted();
    detachSubmitClickListener(); // modal detached, clean up listener

    try {
      modal = await ensureEasyApplyModal({ context: currentContext });
      emitModalReady(modal);
    } catch (error) {
      abort(error);
      throw error;
    }

    observer = new MutationObserver(() => {
      evaluateModalState();
    });

    if (document.body) {
      observer.observe(document.body, observerOptions);
    }

    ensureShadowObservation();
    resetInactivityTimer();
    scheduleEvaluation();

    return modal;
  };

  // Stop monitoring and release internal references.
  const stop = () => {
    if (!running) {
      clearInactivityTimer();
    } else {
      running = false;
      clearInactivityTimer();
      stopRaf();
      disconnectObserver();
    }
    modal = null;
    emittedReview = false;
    setLinkedInSubmitStage(false);
    resetSubmitAttempted();
    detachSubmitClickListener(); // stop monitoring when stopped explicitly
  };

  // Expose the abort promise so callers can await dismissal.
  const waitForAbort = () => abortPromise;

  resetAbortPromise();
  registerCallbacks({
    onModalReady: initialOnModalReady,
    onModalDismissed: initialOnModalDismissed,
    onReviewStep: initialOnReviewStep
  });

  return {
    start,
    stop,
    waitForAbort,
    getModal: () => modal,
    isRunning: () => running,
    abort,
    registerCallbacks,
    setContext
  };
}

let sharedEasyApplyMonitor = null;

export async function ensureEasyApplyMonitor(options = {}) {
  const {
    context = 'autofill',
    onModalReady,
    onModalDismissed,
    onReviewStep
  } = options || {};

  if (!sharedEasyApplyMonitor) {
    sharedEasyApplyMonitor = createEasyApplyModalMonitor();
  }

  sharedEasyApplyMonitor.setContext(context);
  const unregister = sharedEasyApplyMonitor.registerCallbacks({ onModalReady, onModalDismissed, onReviewStep });

  try {
    const modal = await sharedEasyApplyMonitor.start();
    return { monitor: sharedEasyApplyMonitor, modal, unregister };
  } catch (error) {
    unregister();
    if (!sharedEasyApplyMonitor.isRunning()) {
      sharedEasyApplyMonitor = null;
    }
    throw error;
  }
}

export function stopEasyApplyMonitor() {
  if (sharedEasyApplyMonitor) {
    sharedEasyApplyMonitor.stop();
    sharedEasyApplyMonitor = null;
  }
}

// ======== Submission Success Monitor ========
const submissionListeners = new Set();
let submissionMonitor = null;

// Look for a LinkedIn post-apply modal across main DOM and shadow roots.
function scanForSubmissionSuccess() {
  const contexts = [document];
  const outlet = document.querySelector('#interop-outlet');
  if (outlet?.shadowRoot) {
    contexts.push(outlet.shadowRoot);
  }

  const modalSelectors = [
    '[role="dialog"][aria-labelledby="post-apply-modal"]',
    '[data-test-modal][role="dialog"]'
  ];

  for (const contextRoot of contexts) {
    if (!contextRoot) continue;
    for (const selector of modalSelectors) {
      const modals = contextRoot.querySelectorAll(selector);
      for (const modal of modals) {
        const titleElement = modal.querySelector('.jpac-modal-header')
          || modal.querySelector('#post-apply-modal')
          || modal.querySelector('h2, h3');
        const titleText = titleElement?.textContent;
        if (isSubmissionSuccessHeading(titleText)) {
          return modal;
        }
      }
    }
  }

  return null;
}

// Broadcast the success modal to subscribers and emit progress updates.
let submissionConfirmationVersion = 0;
const notifiedSubmissionModals = new WeakSet();
function notifySubmissionSuccess(modal) {
  if (notifiedSubmissionModals.has(modal)) return;
  notifiedSubmissionModals.add(modal);
  submissionConfirmationVersion++;
  // Fan out the detected success modal to every registered consumer.
  // Consumers include auto-apply/autofill flows that may update UI or log outcomes.
  submissionListeners.forEach((listener) => {
    try {
      listener(modal);
    } catch (error) {
      console.error('❌ Error in LinkedIn submission success listener:', error);
    }
  });
  resetSubmitAttempted();
  detachSubmitClickListener();
  try {
    const { update: updateProgress } = createProgressEmitters('linkedin');
    updateProgress('Application', 'submitted', { message: 'Application submitted!' });
  } catch (error) {
    console.warn('⚠️ Unable to emit LinkedIn submission progress update:', error);
  }
  try {
    reportLinkedInApplicationOutcome('Applied');
  } catch (error) {
    console.warn('⚠️ Unable to report LinkedIn application outcome:', error);
  }

  releaseLinkedinLockBoth('auto-apply', 'autofill');
}


// Build a DOM watcher that emits when the submission success modal appears.
function createSubmissionSuccessMonitorInternal() {
  let running = false;
  let observer = null;
  let rafId = null;
  let lastModal = null;
  let observedShadowRoot = null;

  const observerOptions = { childList: true, subtree: true };

  // Poll for success modals and dedupe notifications per element instance.
  const checkSuccess = () => {
    if (!running) return;

    const outlet = document.querySelector('#interop-outlet');
    if (outlet?.shadowRoot && outlet.shadowRoot !== observedShadowRoot) {
      observer?.observe(outlet.shadowRoot, observerOptions);
      observedShadowRoot = outlet.shadowRoot;
    } else if ((!outlet || !outlet.shadowRoot) && observedShadowRoot) {
      observedShadowRoot = null;
    }

    const modal = scanForSubmissionSuccess();
    if (!modal) {
      if (lastModal && !isModalStillAttached(lastModal)) {
        lastModal = null;
      }
      return;
    }

    if (modal !== lastModal) {
      lastModal = modal;
      console.log('✅ LinkedIn submission success detected via monitor');
      notifySubmissionSuccess(modal);
    }
  };

  // Kick the polling loop forward on the next animation frame.
  const scheduleRaf = () => {
    if (!running) return;
    checkSuccess();
    rafId = requestAnimationFrame(scheduleRaf);
  };

  // Start monitoring the DOM for a submission success modal.
  const start = () => {
    if (running) return;
    running = true;
    checkSuccess();

    observer = new MutationObserver(() => {
      checkSuccess();
    });

    if (document.body) {
      observer.observe(document.body, observerOptions);
    }

    scheduleRaf();
  };

  // Stop monitoring and reset cached modal references.
  const stop = () => {
    if (!running) return;
    running = false;
    observer?.disconnect();
    observer = null;
    if (rafId !== null) {
      cancelAnimationFrame(rafId);
      rafId = null;
    }
    lastModal = null;
    observedShadowRoot = null;
  };

  return {
    start,
    stop,
    isRunning: () => running
  };
}

export function ensureLinkedInSubmissionMonitor() {
  if (!submissionMonitor) {
    submissionMonitor = createSubmissionSuccessMonitorInternal();
  }
  submissionMonitor.start();
  return submissionMonitor;
}

export function stopLinkedInSubmissionMonitor() {
  submissionMonitor?.stop();
}

export function subscribeToSubmissionSuccess(listener) {
  if (typeof listener !== 'function') return () => {};
  submissionListeners.add(listener);
  return () => {
    submissionListeners.delete(listener);
  };
}

export function awaitSubmissionSuccess(timeoutMs = 5000) {
  ensureLinkedInSubmissionMonitor();
  return new Promise((resolve, reject) => {
    let timeoutId = null;
    let unsubscribe = () => {};

    const cleanup = () => {
      unsubscribe();
      if (timeoutId) {
        clearTimeout(timeoutId);
        timeoutId = null;
      }
    };

    if (timeoutMs > 0) {
      timeoutId = setTimeout(() => {
        cleanup();
        reject(new Error('Timed out waiting for LinkedIn submission success'));
      }, timeoutMs);
    }

    unsubscribe = subscribeToSubmissionSuccess((modal) => {
      cleanup();
      resolve(modal);
    });
  });
}

// Resume Manager
// Queue-based resume management for multiple applications

export class ResumeManager {
  static lockKey = 'seek_resume_lock';
  static statusKey = 'seek_resume_status';

  // Check if resume management is in progress or completed
  static async getResumeStatus() {
    try {
      const result = await chrome.storage.local.get([this.statusKey]);
      const status = result[this.statusKey];

      if (!status) {
        return { state: 'not_started', processingJobId: null };
      }

      // Check if status is stale (2 minutes for processing, 5 minutes for completed)
      const elapsed = Date.now() - status.timestamp;
      const maxAge = status.state === 'processing' ? 2 * 60 * 1000 : 5 * 60 * 1000;

      if (elapsed > maxAge) {
        console.log(`📄 Resume status expired (${Math.round(elapsed/1000)}s old, state: ${status.state}), auto-clearing`);
        await this.clearResumeStatus();
        return { state: 'not_started', processingJobId: null };
      }

      // Log status for debugging
      console.log(`📄 Resume status: ${status.state} (job: ${status.processingJobId}, age: ${Math.round(elapsed/1000)}s)`);

      return status;
    } catch (error) {
      console.error('❌ Error getting resume status:', error);
      return { state: 'not_started', processingJobId: null };
    }
  }

  // Set resume management status
  static async setResumeStatus(state, processingJobId = null) {
    try {
      const status = {
        state: state, // 'processing', 'completed', 'not_started'
        processingJobId: processingJobId,
        timestamp: Date.now()
      };

      await chrome.storage.local.set({
        [this.statusKey]: status
      });

      console.log(`📄 Resume status set to: ${state} (job: ${processingJobId})`);
    } catch (error) {
      console.error('❌ Error setting resume status:', error);
    }
  }

  // Store info about uploaded resume for reuse
  static async storeSharedResume(resumeUrl, jobId) {
    try {
      const sharedResumeData = {
        resumeUrl: resumeUrl,
        uploadTime: Date.now(),
        firstJobId: jobId,
        usedByJobs: [jobId]
      };

      await chrome.storage.local.set({
        [this.storageKey]: sharedResumeData
      });

      console.log(`📄 Stored shared resume for reuse:`, sharedResumeData);
    } catch (error) {
      console.error('❌ Error storing shared resume:', error);
    }
  }

  // Mark that a job used the shared resume
  static async markResumeUsed(jobId) {
    try {
      const result = await chrome.storage.local.get([this.storageKey]);
      const sharedResume = result[this.storageKey];

      if (sharedResume) {
        if (!sharedResume.usedByJobs.includes(jobId)) {
          sharedResume.usedByJobs.push(jobId);
          await chrome.storage.local.set({
            [this.storageKey]: sharedResume
          });
          console.log(`📄 Marked shared resume as used by job ${jobId}`);
        }
      }
    } catch (error) {
      console.error('❌ Error marking resume used:', error);
    }
  }

  // Get shared resume info
  static async getSharedResumeInfo() {
    try {
      const result = await chrome.storage.local.get([this.storageKey]);
      return result[this.storageKey] || null;
    } catch (error) {
      console.error('❌ Error getting shared resume info:', error);
      return null;
    }
  }

  // Wait for resume management to complete
  static async waitForResumeCompletion(maxWaitTime = 60000) {
    console.log('⏳ Waiting for resume management to complete...');

    const startTime = Date.now();

    while (Date.now() - startTime < maxWaitTime) {
      const status = await this.getResumeStatus();

      if (status.state === 'completed') {
        console.log('✅ Resume management completed, proceeding');
        return true;
      } else if (status.state === 'processing') {
        console.log(`⏳ Resume being processed by job ${status.processingJobId}, waiting...`);
        await new Promise(resolve => setTimeout(resolve, 2000)); // Wait 2 seconds
      } else {
        console.log('❌ Resume management not started');
        return false;
      }
    }

    console.log('⏰ Timeout waiting for resume management');
    return false;
  }

  // Refresh page and mark for autofill continuation
  static async refreshAndSelectNewestResume() {
    try {
      console.log('🔄 Refreshing page to see updated resume list...');

      // Mark that we need to continue autofill after refresh
      const currentJobId = window.location.href.match(/\/job\/(\d+)/)?.[1];
      if (currentJobId) {
        // Preserve the flow state and mark for continuation
        const flowKey = `seek_flow_${currentJobId}`;
        const flowData = await chrome.storage.local.get([flowKey]);

        await chrome.storage.local.set({
          [`seek_refresh_continue_${currentJobId}`]: {
            needsContinuation: true,
            timestamp: Date.now(),
            preservedFlowData: flowData[flowKey] // Preserve the original flow data
          }
        });
        console.log('📝 Marked for autofill continuation after refresh with preserved flow state');
      }

      // Refresh the page
      window.location.reload();
      return true;
    } catch (error) {
      console.error('❌ Error refreshing page:', error);
      return false;
    }
  }

  // Select newest resume without refresh (for first application)
  static async selectNewestResumeDirectly() {
    try {
      console.log('📄 Selecting newest resume directly...');

      // Ensure "Select a resumé" radio is selected
      const selectResumeRadio = document.querySelector('input[data-testid="resume-method-change"]');
      if (selectResumeRadio && !selectResumeRadio.checked) {
        selectResumeRadio.click();
        console.log('✅ Selected "Select a resumé" option');
        await new Promise(resolve => setTimeout(resolve, 500));
      }

      // Find and select from dropdown
      const resumeDropdown = document.querySelector('select[data-testid="select-input"]');
      if (resumeDropdown && resumeDropdown.options.length > 1) {
        resumeDropdown.selectedIndex = 1; // First option after "Please select"
        resumeDropdown.dispatchEvent(new Event('change', { bubbles: true }));

        const selectedOption = resumeDropdown.options[1];
        console.log('✅ Selected newest resume directly:', selectedOption.text);
        return true;
      }

      console.log('⚠️ No resume dropdown found or empty');
      return false;
    } catch (error) {
      console.error('❌ Error selecting newest resume:', error);
      return false;
    }
  }

  // Check if page needs autofill continuation after refresh
  static async checkForContinuation() {
    try {
      const currentJobId = window.location.href.match(/\/job\/(\d+)/)?.[1];
      if (!currentJobId) return null;

      const continueKey = `seek_refresh_continue_${currentJobId}`;
      const result = await chrome.storage.local.get([continueKey]);
      const continueData = result[continueKey];

      if (continueData && continueData.needsContinuation) {
        // Check if continuation is recent (prevent infinite loops)
        const timeSinceMarked = Date.now() - continueData.timestamp;
        if (timeSinceMarked > 30000) { // 30 seconds timeout
          console.log('⏰ Continuation marker too old, cleaning up');
          await chrome.storage.local.remove([continueKey]);
          return null;
        }

        console.log('🔄 Found continuation marker for job', currentJobId);

        // Restore the flow state if it was preserved
        if (continueData.preservedFlowData) {
          const flowKey = `seek_flow_${currentJobId}`;
          await chrome.storage.local.set({
            [flowKey]: continueData.preservedFlowData
          });
          console.log('🔄 Restored flow state for job', currentJobId);
        }

        // Clean up the continuation marker
        await chrome.storage.local.remove([continueKey]);

        // Select newest resume after refresh
        const success = await this.selectNewestResumeAfterRefresh();
        if (success) {
          console.log('✅ Resume selected after refresh, ready to continue autofill');
          return { jobId: currentJobId, shouldContinue: true };
        }
      }

      return null;
    } catch (error) {
      console.error('❌ Error checking for continuation:', error);
      return null;
    }
  }

  // Select newest resume after page refresh
  static async selectNewestResumeAfterRefresh() {
    try {
      console.log('📄 Selecting newest resume after refresh...');

      // Wait for page to be fully loaded
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Ensure "Select a resumé" radio is selected
      const selectResumeRadio = document.querySelector('input[data-testid="resume-method-change"]');
      if (selectResumeRadio && !selectResumeRadio.checked) {
        selectResumeRadio.click();
        console.log('✅ Selected "Select a resumé" option');
        await new Promise(resolve => setTimeout(resolve, 500));
      }

      // Find and select from dropdown
      const resumeDropdown = document.querySelector('select[data-testid="select-input"]');
      if (resumeDropdown && resumeDropdown.options.length > 1) {
        resumeDropdown.selectedIndex = 1; // First option after "Please select"
        resumeDropdown.dispatchEvent(new Event('change', { bubbles: true }));

        const selectedOption = resumeDropdown.options[1];
        console.log('✅ Selected newest resume after refresh:', selectedOption.text);
        return true;
      }

      console.log('⚠️ No resume dropdown found after refresh');
      return false;
    } catch (error) {
      console.error('❌ Error selecting resume after refresh:', error);
      return false;
    }
  }

  // Clear all resume management data
  static async clearResumeStatus() {
    try {
      // Get current status for logging
      const result = await chrome.storage.local.get([this.statusKey]);
      const oldStatus = result[this.statusKey];

      await chrome.storage.local.remove([this.statusKey, this.lockKey]);

      // Also clear any continuation markers
      const allData = await chrome.storage.local.get(null);
      const continuationKeys = Object.keys(allData).filter(key => key.startsWith('seek_refresh_continue_'));
      if (continuationKeys.length > 0) {
        await chrome.storage.local.remove(continuationKeys);
      }

      console.log('🧹 Cleared resume management status and continuation markers');
      if (oldStatus) {
        console.log(`   Previous status: ${oldStatus.state} (job: ${oldStatus.processingJobId})`);
      }
    } catch (error) {
      console.error('❌ Error clearing resume status:', error);
    }
  }

  // Diagnostic tool: Check current resume queue state
  static async diagnoseResumeQueue() {
    try {
      const status = await this.getResumeStatus();
      const activeCount = await this.getActiveApplicationCount();

      console.log('🔍 Resume Queue Diagnostic:');
      console.log('  Status:', status);
      console.log('  Active applications:', activeCount);

      if (status.state === 'processing') {
        const elapsed = Date.now() - status.timestamp;
        console.log(`  ⚠️ STUCK: Job ${status.processingJobId} has been processing for ${Math.round(elapsed/1000)}s`);
        console.log(`  Recommendation: Clear with ResumeManager.clearResumeStatus()`);
      }

      return { status, activeCount };
    } catch (error) {
      console.error('❌ Error diagnosing queue:', error);
      return null;
    }
  }

  // Get count of active applications
  static async getActiveApplicationCount() {
    try {
      const result = await chrome.storage.local.get(null);
      const activeFlows = Object.keys(result).filter(key => 
        key.startsWith('seek_flow_') && result[key]?.active
      );
      return activeFlows.length;
    } catch (error) {
      console.error('❌ Error getting active application count:', error);
      return 0;
    }
  }

  // Check if tailored resume is enabled for a specific job
  static async isTailoredResumeEnabled(jobId) {
    try {
      // Get the switch state from the UI component
      // For now, we'll check a storage key, but this could be enhanced
      const result = await chrome.storage.local.get(['tailored_resume_enabled']);
      return result.tailored_resume_enabled || false;
    } catch (error) {
      console.error('❌ Error checking tailored resume setting:', error);
      return false; // Default to false (shared resume)
    }
  }
}

